<?php
require_once __DIR__.'/../includes/auth.php';requireLogin();$u=currentUser();if(isPost()){verifyCsrf();$id=(int)($_POST['id']??0);$s=db()->prepare('SELECT user_id FROM news WHERE id=? AND deleted_at IS NOT NULL');$s->execute([$id]);$a=$s->fetch();if($a&&(in_array($u['role'],['admin','editor'],true)||(int)$a['user_id']===(int)$u['id'])){db()->prepare('UPDATE news SET deleted_at=NULL,updated_at=NOW() WHERE id=?')->execute([$id]);flash('success','تمت استعادة الخبر.');}redirect(url('admin/deleted-news.php'));}$where="n.deleted_at IS NOT NULL".($u['role']==='author'?' AND n.user_id='.(int)$u['id']:'');$rows=db()->query("SELECT n.id,n.title,n.deleted_at,c.name category,u.name author FROM news n LEFT JOIN categories c ON c.id=n.category_id LEFT JOIN users u ON u.id=n.user_id WHERE {$where} ORDER BY n.deleted_at DESC")->fetchAll();$pageTitle='الأخبار المحذوفة';require __DIR__.'/includes/header.php';?><div class="card stat-card"><div class="card-body"><div class="table-responsive"><table class="table align-middle"><thead><tr><th>العنوان</th><th>التصنيف</th><th>الكاتب</th><th>تاريخ الحذف</th><th></th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['title'])?></td><td><?=e($r['category']??'—')?></td><td><?=e($r['author']??'—')?></td><td><?=formatDate($r['deleted_at'])?></td><td><form method="post"><?=csrfField()?><input type="hidden" name="id" value="<?=$r['id']?>"><button class="btn btn-sm btn-success">استعادة</button></form></td></tr><?php endforeach;if(!$rows):?><tr><td colspan="5" class="text-center py-5">سلة المحذوفات فارغة.</td></tr><?php endif;?></tbody></table></div></div></div><?php require __DIR__.'/includes/footer.php';?>
